import { useSyncExternalStore } from 'react'

// Set by public/config.js (generated by CD on Azure), loaded before this bundle.
declare global {
  interface Window {
    APP_CONFIG?: { CATALOG_URL: string; MATCHES_URL: string }
  }
}

export type Service = 'catalog' | 'matches'

const config = window.APP_CONFIG ?? {
  CATALOG_URL: 'http://localhost:8001',
  MATCHES_URL: 'http://localhost:8002',
}

function baseUrl(service: Service): string {
  const url = service === 'catalog' ? config.CATALOG_URL : config.MATCHES_URL
  return url.replace(/\/+$/, '')
}

// A cold start on Azure (container starting, database resuming) can take about a minute.
const STARTUP_WAIT_MS = 90_000
const FIRST_RETRY_MS = 2_000
const MAX_RETRY_MS = 15_000

// How many requests are currently waiting for a service to start; drives the banner.
let waitingRequests = 0
const listeners = new Set<() => void>()

function setWaiting(delta: number) {
  waitingRequests += delta
  listeners.forEach((notify) => notify())
}

function subscribe(notify: () => void) {
  listeners.add(notify)
  return () => {
    listeners.delete(notify)
  }
}

/** True while any request is retrying because a service is still starting up. */
export function useStartingUp(): boolean {
  return useSyncExternalStore(subscribe, () => waitingRequests > 0)
}

function sleep(ms: number) {
  return new Promise((resolve) => window.setTimeout(resolve, ms))
}

type ErrorBody = { detail?: unknown } | null

export function readError(data: ErrorBody): string {
  if (typeof data?.detail === 'string') return data.detail
  if (Array.isArray(data?.detail)) {
    return data.detail
      .map((item) => (item && typeof item.msg === 'string' ? item.msg : 'Invalid value'))
      .join(' ')
  }
  return 'Request failed'
}

/**
 * Call one of the two services and return its JSON.
 *
 * "Still starting" is retried with backoff for up to STARTUP_WAIT_MS:
 *  - fetch itself failed (no answer: container starting, or the service is down);
 *  - a 503 without a JSON `detail` (Container Apps' "App port is not ready").
 * A 503 *with* a `detail` comes from our own code (e.g. "catalog unavailable") and is
 * shown to the user immediately, like any other error.
 */
export async function api<T>(service: Service, path: string, options?: RequestInit): Promise<T> {
  const deadline = Date.now() + STARTUP_WAIT_MS
  let delay = FIRST_RETRY_MS
  let waiting = false

  try {
    for (;;) {
      let response: Response | null
      try {
        response = await fetch(baseUrl(service) + path, {
          ...options,
          headers: {
            'Content-Type': 'application/json',
            ...(options?.headers ?? {}),
          },
        })
      } catch {
        response = null
      }

      const data: ErrorBody = response ? await response.json().catch(() => null) : null
      const startingUp =
        response === null || (response.status === 503 && typeof data?.detail !== 'string')

      if (startingUp && Date.now() + delay < deadline) {
        if (!waiting) {
          waiting = true
          setWaiting(1)
        }
        await sleep(delay)
        delay = Math.min(delay * 2, MAX_RETRY_MS)
        continue
      }

      if (response === null) {
        throw new Error(`Could not reach the ${service} service. It may be down; try again in a minute.`)
      }
      if (startingUp) {
        throw new Error(`The ${service} service is still starting up. Try again in a moment.`)
      }
      if (!response.ok) {
        throw new Error(readError(data))
      }
      return data as T
    }
  } finally {
    if (waiting) setWaiting(-1)
  }
}
